    pub fn begin(image: &str) {
        append(&[format!(
            "== building {image} at {}",
            crate::self_update::utc_time(crate::self_update::now())
        )]);
    }

    /// A line the build printed.
    pub fn line(line: &str) {
        append(&[line.to_string()]);
    }
}

